code.cpp:
class Solution {
public:
    int countVowelSubstrings(string word) {
        int n = word.size();
        int result = 0;
        int i = 0;
        while (i < n) {
            if (!isVowel(word[i])) {
                i++;
                continue;
            }
            int segStart = i;
            int left = i;
            int counts[5] = {0, 0, 0, 0, 0};
            int distinct = 0;
            while (i < n && isVowel(word[i])) {
                int idx = vowelIdx(word[i]);
                if (counts[idx] == 0) distinct++;
                counts[idx]++;
                while (distinct == 5) {
                    int lidx = vowelIdx(word[left]);
                    counts[lidx]--;
                    if (counts[lidx] == 0) distinct--;
                    left++;
                }
                result += left - segStart;
                i++;
            }
        }
        return result;
    }
private:
    bool isVowel(char c) {
        return c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u';
    }
    int vowelIdx(char c) {
        if (c == 'a') return 0;
        if (c == 'e') return 1;
        if (c == 'i') return 2;
        if (c == 'o') return 3;
        return 4;
    }
};
